<script setup lang="ts">
import MoneyInput from './MoneyInput.vue';
import { computed, reactive, watch } from 'vue';
import { state, mutate, mutation, today } from '../store.ts';
import { money, normalize, localDay, duplicateCandidates, type Transaction, type Transfer, type Review } from '../domain.ts';
import { parseMoney } from '../contracts.ts';
import { fromZonedTime } from '../timezone.ts';
import Icon from './Icon.vue';
const props = defineProps<{ kind: string; existing?: Transaction | Transfer; review?: Review; initialGoal?: import('../domain.ts').SavingsGoal }>();
const emit = defineEmits<{ saved: []; dirty: [value: boolean] }>();
const accounts = computed(() => state.data.accounts.filter(row => !row.archived));
const isQRIS = computed(() => props.review?.source === 'qris' || (props.existing && 'source' in props.existing && props.existing.source === 'qris'));
const form = reactive({ kind: props.kind, amount: props.existing?.amount ?? props.review?.amount.value ?? '', account: (props.existing && 'accountID' in props.existing ? props.existing.accountID : props.existing && 'fromAccountID' in props.existing ? props.existing.fromAccountID : accounts.value[0]?.id) ?? '', to: props.existing && 'toAccountID' in props.existing ? props.existing.toAccountID : accounts.value[1]?.id ?? '', goal: props.existing && 'goalID' in props.existing ? props.existing.goalID ?? '' : props.initialGoal?.id ?? '', category: props.existing && 'categoryID' in props.existing ? props.existing.categoryID : props.initialGoal ? state.data.categories.find(row => row.systemKey === 'goal')?.id ?? '' : props.review?.source === 'qris' ? state.data.categories.find(row => row.systemKey === 'qris')?.id ?? '' : '', date: (props.existing ? localDay(props.existing.occurredAt, state.timezone) : undefined) ?? props.review?.date.value ?? today(), merchant: props.existing && 'merchant' in props.existing ? props.existing.merchant ?? '' : props.review?.merchant.value ?? '', note: props.existing?.note ?? '', duplicateConfirmed: false });
const errors = reactive<Record<string, string>>({});
const categories = computed(() => state.data.categories.filter(row => !row.archived && row.kind === form.kind));
const goalSelected = computed(() => form.kind === 'expense' && categories.value.find(row => row.id === form.category)?.systemKey === 'goal');
watch(() => form.category, () => { if (!goalSelected.value) form.goal = ''; });
const candidates = computed(() => props.review ? duplicateCandidates(state.data, { ...props.review, amount: { ...props.review.amount, value: form.amount }, merchant: { ...props.review.merchant, value: form.merchant }, date: { ...props.review.date, value: form.date } }, form.account) : []);
const negative = computed(() => { try { return BigInt(accounts.value.find(row => row.id === form.account)?.balance ?? '0') < parseMoney(form.amount) && form.kind !== 'income'; } catch { return false; } });
watch(() => form.kind, () => { form.category = props.review?.source === 'qris' ? categories.value.find(row => row.systemKey === 'qris')?.id ?? '' : categories.value[0]?.id ?? ''; form.goal = ''; }, { immediate: !form.category });
watch(form, () => emit('dirty', true));
watch(() => form.merchant, value => { if (props.existing || goalSelected.value || isQRIS.value) return; const rule = [...state.data.merchantRules].sort((left, right) => right.priority - left.priority).find(row => row.matchType === 'exact' ? normalize(value) === row.normalizedPattern : row.matchType === 'prefix' ? normalize(value).startsWith(row.normalizedPattern) : normalize(value).includes(row.normalizedPattern)); if (rule && categories.value.some(row => row.id === rule.categoryID)) form.category = rule.categoryID; });
async function save() {
  for (const key of Object.keys(errors)) delete errors[key];
  try { parseMoney(form.amount); } catch { errors.amount = 'Isi Rupiah bulat positif, maksimal Rp999.999.999.999.'; }
  if (!form.account) errors.account = 'Pilih akun aktif.';
  if (form.kind === 'transfer' && form.account === form.to) errors.to = 'Akun asal dan tujuan harus berbeda.';
  if (form.kind !== 'transfer' && !form.category) errors.category = 'Pilih kategori.';
  if (goalSelected.value && !state.data.goals?.some(row => row.id === form.goal)) errors.goal = 'Pilih target.';
  if (!form.date || !Number.isFinite(Date.parse(form.date))) errors.date = 'Isi tanggal yang valid.';
  if (candidates.value.length && !form.duplicateConfirmed) errors.duplicate = 'Periksa transaksi mirip sebelum menyimpan.';
  if (Object.keys(errors).length) { document.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus(); return; }
  const occurredAt = props.existing && localDay(props.existing.occurredAt, state.timezone) === form.date ? props.existing.occurredAt : fromZonedTime(form.date, state.timezone);
  let operation: string, payload: Record<string, unknown>;
  if (form.kind === 'transfer') { operation = props.existing ? 'update_transfer' : 'create_transfer'; payload = { ...mutation(), p_from_account_id: form.account, p_to_account_id: form.to, p_amount: form.amount, p_occurred_at: occurredAt, p_note: form.note || null, ...(props.existing ? { p_transfer_id: props.existing.id, p_expected_version: props.existing.version } : {}) }; }
  else if (props.review) { operation = 'confirm_review_item'; payload = { id: props.review.id, transaction: { kind: form.kind, amount: form.amount, accountID: form.account, categoryID: form.category, occurredAt, merchant: form.merchant || null, note: form.note || null, source: props.review.source } }; }
  else { operation = props.existing ? 'update_transaction' : 'create_transaction'; payload = { ...mutation(), p_type: form.kind, p_amount: form.amount, p_account_id: form.account, p_category_id: form.category, p_goal_id: goalSelected.value ? form.goal : null, p_occurred_at: occurredAt, p_merchant: form.merchant || null, p_note: form.note || null, ...(props.existing ? { p_transaction_id: props.existing.id, p_expected_version: props.existing.version } : { p_source: 'manual' }) }; }
  if (await mutate(operation, payload)) { emit('dirty', false); emit('saved'); }
}
</script>
<template><form class="entry-form" @submit.prevent="save"><div v-if="kind !== 'transfer' && !isQRIS" class="segmented"><button type="button" :class="{ active: form.kind === 'expense' }" @click="form.kind = 'expense'">Pengeluaran</button><button type="button" :class="{ active: form.kind === 'income' }" @click="form.kind = 'income'">Pemasukan</button></div><label class="amount-input">Nominal<div><span>Rp</span><MoneyInput v-model="form.amount" aria-label="Nominal" placeholder="0" :aria-invalid="!!errors.amount" aria-describedby="amount-error" required /></div><small v-if="errors.amount" id="amount-error" class="error-text">{{ errors.amount }}</small></label><div class="form-grid"><label>{{ form.kind === 'transfer' ? 'Dari akun' : 'Akun' }}<select v-model="form.account" required :aria-invalid="!!errors.account"><option value="" disabled>Pilih akun</option><option v-for="account in accounts" :key="account.id" :value="account.id">{{ account.name }}</option></select></label><label v-if="form.kind === 'transfer'">Ke akun<select v-model="form.to" aria-label="Ke akun" aria-describedby="to-error" required :aria-invalid="!!errors.to"><option v-for="account in accounts" :key="account.id" :value="account.id">{{ account.name }}</option></select><small v-if="errors.to" id="to-error" class="error-text">{{ errors.to }}</small></label><label v-else>Kategori<select v-model="form.category" :disabled="isQRIS" required :aria-invalid="!!errors.category"><option value="" disabled>Pilih kategori</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></label><label v-if="goalSelected" class="full-width">Target<select v-model="form.goal" required :aria-invalid="!!errors.goal"><option value="" disabled>Pilih target</option><option v-for="goal in state.data.goals ?? []" :key="goal.id" :value="goal.id">{{ goal.name }}</option></select><small v-if="errors.goal" class="error-text">{{ errors.goal }}</small></label><label>Tanggal<input v-model="form.date" type="date" required :aria-invalid="!!errors.date"></label><label v-if="form.kind !== 'transfer'"><span class="field-label">Merchant <span class="optional">opsional</span></span><input v-model="form.merchant" maxlength="160" placeholder="Misalnya, Kedai Sore"></label></div><label><span class="field-label">Catatan <span class="optional">opsional</span></span><textarea v-model="form.note" rows="2" maxlength="2000" placeholder="Biar nanti mudah diingat"></textarea></label><p v-if="negative" class="callout sun">Saldo akun akan negatif. Tetap boleh dicatat; periksa kembali nominal dan akun.</p><div v-if="candidates.length" class="callout sun"><strong>Ditemukan transaksi mirip. Periksa sebelum menyimpan.</strong><p v-for="candidate in candidates" :key="candidate.id">{{ candidate.merchant }} · {{ money(candidate.amount) }} · {{ candidate.occurredAt.slice(0, 10) }}</p><label class="checkbox"><input v-model="form.duplicateConfirmed" type="checkbox"> Saya sudah memeriksa; ini transaksi berbeda.</label><small v-if="errors.duplicate" class="error-text">{{ errors.duplicate }}</small></div><p v-if="review?.source === 'qris'" class="fine-print">Kode QR membantu mengisi catatan; pembayaran dilakukan di aplikasi pembayaran Anda. Menekan Simpan mengonfirmasi catatan sudah dibayar, bukan memproses pembayaran.</p><p v-if="state.error" class="error-text" role="alert">{{ state.error }}</p><button class="primary full" :disabled="state.saving || (!state.online && state.mode !== 'demo')"><Icon name="check" />{{ state.saving ? 'Menyimpan…' : props.existing ? 'Simpan perubahan' : 'Simpan catatan' }}</button><p v-if="!state.online && state.mode !== 'demo'" class="fine-print">Perlu internet. Web R1 tidak menyimpan antrean offline.</p></form></template>
